// Names a session after the GitLab MR or issue in its first message, and
// serves the /gitlab-titler command (see tui.ts) with its on/off setting and
// retitling.
//
// OpenCode runs the `title` hook once, when it generates the session title, so
// the name is set before any work starts and nothing renames it later. See
// hook.ts for what the hook does.
//
// Imports from @opencode/plugin are type-only, except the RPC contract in
// rpc.ts, which needs the package installed (`bun install`).

import type { Plugin } from "@opencode/plugin"
import { configPath, loadOptions } from "./config.ts"
import { createClient, glabRunner } from "./gitlab.ts"
import { buildGuidance } from "./guidance.ts"
import { handleTitle } from "./hook.ts"
import type { Options } from "./options.ts"
import { inferPlace } from "./origin.ts"
import { GitlabTitler } from "./rpc.ts"
import type { RetitleDeps } from "./retitle.ts"
import { createService, Failed } from "./service.ts"
import { chooseTitleModel, createState } from "./state.ts"

const plugin: Plugin.Plugin = {
  id: "opencode-gitlab-titler",
  async setup(ctx) {
    const fileOptions = await loadOptions()
    if (ctx.options && Object.keys(ctx.options).length > 0) {
      console.warn(`[gitlab-titler] options in the plugins entry are ignored. Move them to ${configPath()}`)
    }

    const client = createClient(glabRunner(fileOptions.timeoutSeconds))
    const state = createState(ctx.storage, ctx.location.project.id)

    // The host and project come from the git origin remote of this location. They are
    // read on every use, so a remote added or changed later applies without a reload.
    const resolveOptions = async (): Promise<Options> => ({ ...fileOptions, ...(await inferPlace(ctx.location.directory)) })

    const retitleDeps = async (): Promise<RetitleDeps> => ({
      options: await resolveOptions(),
      client,
      messages: (sessionID) => ctx.session.context({ sessionID }),
      generate: async (prompt, model) => (await ctx.experimental.generate.text({ prompt, model })).text,
      update: (sessionID, title) => ctx.session.update({ sessionID, title }),
      // Read on every call, so a change to agents.title.model applies without a restart.
      titleModel: async () => {
        const agent = await ctx.agent.get({ agentID: "title" }).catch(() => undefined)
        return chooseTitleModel(agent?.data.model, await state.titleModel())
      },
    })

    const service = createService(state, retitleDeps)

    const hook = await ctx.session.hook("title", async (event) => {
      const options = await resolveOptions()
      await handleTitle(event, { options, client, guidance: buildGuidance(options), state })
    })

    const rpc = await ctx.rpc.register(GitlabTitler, {
      status: () => service.status(),

      setEnabled: (input) => service.setEnabled((input as { enabled: boolean }).enabled),

      async retitle(input, context) {
        try {
          return await service.retitle((input as { sessionID: string }).sessionID)
        } catch (error) {
          if (!(error instanceof Failed)) throw error
          return context.error("failed", error.message, { reason: error.message })
        }
      },
    })

    return async () => {
      await rpc.dispose()
      await hook.dispose()
    }
  },
}

export default plugin
